import type { Bookmark } from './types'
import { BookmarkCard } from './BookmarkCard'

interface Props { bookmarks: Bookmark[]; isLoading: boolean; error?: string | null; hasCriteria?: boolean; scope?: 'all' | 'unread-read-later'; onReset?: () => void; onReadingChange: (bookmark: Bookmark, readLater: boolean, isRead: boolean) => Promise<void>; onEdit: (bookmark: Bookmark) => void; onDelete: (bookmark: Bookmark, trigger: HTMLButtonElement) => void }
export function BookmarkLibrary({ bookmarks, isLoading, error, hasCriteria, scope = 'all', onReset, ...actions }: Props) {
  if (isLoading) return <div className="state-panel" role="status"><span className="spinner" />Loading your bookmarks…</div>
  if (error) return <div className="state-panel error" role="alert"><h3>Your library couldn’t be loaded</h3><p>{error}</p></div>
  if (!bookmarks.length) return <div className="state-panel"><div className="empty-glyph" aria-hidden="true">⌑</div><h3>{scope === 'unread-read-later' ? 'Your reading queue is clear' : hasCriteria ? 'No bookmarks match' : 'Your library is ready for its first link'}</h3><p>{scope === 'unread-read-later' ? 'Add a bookmark to read later, or mark a read item unread.' : hasCriteria ? 'Try removing a filter or simplifying the search.' : 'Paste a web address above and the page details will be filled in for you.'}</p>{hasCriteria && onReset ? <button className="button secondary" onClick={onReset}>Reset search and filters</button> : null}</div>
  return <div className="bookmark-grid">{bookmarks.map((bookmark) => <BookmarkCard key={bookmark.id} bookmark={bookmark} {...actions} />)}</div>
}

import type { Bookmark } from './types'
import { ReadingStatusControls } from '../read-later/ReadingStatusControls'

interface Props { bookmark: Bookmark; onReadingChange: (bookmark: Bookmark, readLater: boolean, isRead: boolean) => Promise<void>; onEdit: (bookmark: Bookmark) => void; onDelete: (bookmark: Bookmark, trigger: HTMLButtonElement) => void }
export function BookmarkCard({ bookmark, onReadingChange, onEdit, onDelete }: Props) {
  let hostname = bookmark.url
  try { hostname = new URL(bookmark.url).hostname } catch { /* display original */ }
  return <article className="bookmark-card" id={`bookmark-${bookmark.id}`} tabIndex={-1}>
    <div className="bookmark-main"><div className="site-icon" aria-hidden="true">{bookmark.iconUrl ? <img src={bookmark.iconUrl} alt="" /> : hostname.slice(0, 1).toUpperCase()}</div><div className="bookmark-copy"><div className="bookmark-title-row"><h3><a href={bookmark.url} target="_blank" rel="noopener noreferrer">{bookmark.title}<span className="external-mark" aria-label="opens in a new tab">↗</span></a></h3>{bookmark.readLater && <span className={`status-badge ${bookmark.isRead ? 'read' : ''}`}>{bookmark.isRead ? 'Read' : 'Unread'}</span>}</div><p className="bookmark-url">{hostname}</p>{bookmark.description && <p className="bookmark-description">{bookmark.description}</p>}{bookmark.notes && <p className="bookmark-notes"><span>Note</span> {bookmark.notes}</p>}<div className="tag-list" aria-label="Tags">{bookmark.tags.map((tag) => <span className="tag" key={tag}>{tag}</span>)}</div></div></div>
    <footer><time dateTime={bookmark.createdAt}>Saved {new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' }).format(new Date(bookmark.createdAt))}</time><div className="card-actions"><ReadingStatusControls bookmark={bookmark} onChange={(readLater, isRead) => onReadingChange(bookmark, readLater, isRead)} /><button className="button icon-button" aria-label={`Edit ${bookmark.title}`} onClick={() => onEdit(bookmark)}>Edit</button><button className="button icon-button danger-text" aria-label={`Delete ${bookmark.title}`} onClick={(e) => onDelete(bookmark, e.currentTarget)}>Delete</button></div></footer>
  </article>
}

